document.addEventListener("DOMContentLoaded",()=>{const l=document.querySelector(".mobile-toggle"),e=document.querySelector(".nav-links-list");l&&e&&(l.addEventListener("click",()=>{e.classList.toggle("mobile-open"),document.getElementById("mainNav")?.classList.add("scrolled")}),e.querySelectorAll("a").forEach(o=>{o.addEventListener("click",()=>e.classList.remove("mobile-open"))}));const t=document.getElementById("mainNav");t&&window.addEventListener("scroll",()=>{window.scrollY>60?t.classList.add("scrolled"):t.classList.remove("scrolled")}),document.querySelectorAll('a[href^="#"]').forEach(o=>{o.addEventListener("click",function(s){const n=this.getAttribute("href");if(n.length>1){const c=document.querySelector(n);c&&(s.preventDefault(),c.scrollIntoView({behavior:"smooth"}))}})})});
